from pathlib import Path

p = Path('src/App.tsx')
s = p.read_text(encoding='utf-8')
s = s.replace("  RotateCcw\n} from 'lucide-react';", "  RotateCcw,\n  Trash2\n} from 'lucide-react';", 1)
s = s.replace("  const [newTreeCatId, setNewTreeCatId] = useState<number>(1);\n  const [newTreeTroncoId, setNewTreeTroncoId] = useState<number>(2);", "  const [newTreeCatId, setNewTreeCatId] = useState<number>(1);\n  const [newTreeTroncoId, setNewTreeTroncoId] = useState<number>(2);\n  const [adminManagePositionIndex, setAdminManagePositionIndex] = useState<number>(7);\n  const [adminManageUserId, setAdminManageUserId] = useState<number>(2);\n  const [adminArchiveReason, setAdminArchiveReason] = useState<string>('Arquivamento administrativo');", 1)
old = '''  const handleCreateTree = async (e: React.FormEvent) => {\n    e.preventDefault();\n    try {\n      const res = await dataStore.createTreeAction(newTreeCatId, newTreeTroncoId);\n      if (res.success) {\n        showToast(`✓ Nova árvore comunitária criada com sucesso (#${res.treeId})!`);\n        setShowCreateTreeModal(false);\n        await fetchState();\n      } else {\n        showToast('Erro: ' + res.error);\n      }\n    } catch (e: any) {\n      showToast('Erro: ' + e.message);\n    }\n  };\n'''
new = '''  const handleCreateTree = async (e: React.FormEvent) => {\n    e.preventDefault();\n    try {\n      const res = await dataStore.createTreeAction(newTreeCatId, newTreeTroncoId);\n      if (res.success && res.result) {\n        openActionRequest(res.result.request_url);\n        showToast('Solicitação de criação da árvore aberta no GitHub.');\n        setShowCreateTreeModal(false);\n      } else {\n        showToast('Erro: ' + res.error);\n      }\n    } catch (e: any) {\n      showToast('Erro: ' + e.message);\n    }\n  };\n\n  const handleArchiveTree = async (tree: Tree) => {\n    if (!tree || tree.status !== 'active') return showToast('Somente árvores ativas podem ser arquivadas.');\n    const ok = window.confirm(`Arquivar a árvore ${tree.tree_code}? O histórico será mantido e os links serão desativados.`);\n    if (!ok) return;\n    try {\n      const res = await dataStore.archiveTreeAction(tree.id, adminArchiveReason);\n      if (res.success && res.result) {\n        openActionRequest(res.result.request_url);\n        showToast('Solicitação de arquivamento aberta no GitHub.');\n      } else {\n        showToast('Erro: ' + res.error);\n      }\n    } catch (e: any) {\n      showToast('Erro: ' + e.message);\n    }\n  };\n\n  const handleAssignTreePosition = async () => {\n    if (!adminTree) return showToast('Selecione uma árvore.');\n    try {\n      const res = await dataStore.assignTreePositionAction(adminTree.id, adminManagePositionIndex, adminManageUserId);\n      if (res.success && res.result) {\n        openActionRequest(res.result.request_url);\n        showToast('Solicitação de posicionamento aberta no GitHub.');\n      } else {\n        showToast('Erro: ' + res.error);\n      }\n    } catch (e: any) {\n      showToast('Erro: ' + e.message);\n    }\n  };\n\n  const handleClearTreePosition = async (positionIndex: number) => {\n    if (!adminTree) return showToast('Selecione uma árvore.');\n    const ok = window.confirm(`Liberar a posição #${positionIndex} da árvore ${adminTree.tree_code}?`);\n    if (!ok) return;\n    try {\n      const res = await dataStore.clearTreePositionAction(adminTree.id, positionIndex);\n      if (res.success && res.result) {\n        openActionRequest(res.result.request_url);\n        showToast('Solicitação de liberação da posição aberta no GitHub.');\n      } else {\n        showToast('Erro: ' + res.error);\n      }\n    } catch (e: any) {\n      showToast('Erro: ' + e.message);\n    }\n  };\n'''
s = s.replace(old, new, 1)
ui = '''                      {renderActiveModel(adminTreePositions)}\n\n                      <div className=\"p-3 bg-slate-900 border border-slate-800 rounded-2xl space-y-3 text-xs\">\n                        <div className=\"flex items-center justify-between gap-2\">\n                          <div>\n                            <div className=\"font-bold text-slate-100\">Gestão da árvore</div>\n                            <div className=\"text-[10px] text-slate-400\">Arquivar árvore, escolher membros e liberar posições.</div>\n                          </div>\n                          <button type=\"button\" onClick={() => handleArchiveTree(adminTree)} className=\"px-2.5 py-1.5 rounded-xl bg-rose-950/80 hover:bg-rose-900 text-rose-300 border border-rose-800 text-[10px] font-bold flex items-center gap-1\">\n                            <Trash2 className=\"w-3.5 h-3.5\" />\n                            <span>Arquivar</span>\n                          </button>\n                        </div>\n\n                        <div className=\"space-y-1.5\">\n                          <label className=\"text-[10px] uppercase tracking-wide text-slate-500 font-bold\">Motivo do arquivamento</label>\n                          <input type=\"text\" value={adminArchiveReason} onChange={(e) => setAdminArchiveReason(e.target.value)} className=\"w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-slate-100 outline-none focus:border-rose-700\" />\n                        </div>\n\n                        <div className=\"grid grid-cols-1 gap-2\">\n                          <div className=\"space-y-1.5\">\n                            <label className=\"text-[10px] uppercase tracking-wide text-slate-500 font-bold\">Posição</label>\n                            <select value={adminManagePositionIndex} onChange={(e) => setAdminManagePositionIndex(parseInt(e.target.value))} className=\"w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-slate-100 outline-none\">\n                              {adminTreePositions.map(pos => (\n                                <option key={pos.position_index} value={pos.position_index}>\n                                  #{pos.position_index} · {pos.status === 'occupied' ? `ocupada por @${pos.username}` : 'vaga'}\n                                </option>\n                              ))}\n                            </select>\n                          </div>\n\n                          <div className=\"space-y-1.5\">\n                            <label className=\"text-[10px] uppercase tracking-wide text-slate-500 font-bold\">Membro</label>\n                            <select value={adminManageUserId} onChange={(e) => setAdminManageUserId(parseInt(e.target.value))} className=\"w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-slate-100 outline-none\">\n                              {allUsers.filter(u => u.id !== 1 && u.status === 'active').map(user => (\n                                <option key={user.id} value={user.id}>\n                                  {user.full_name || user.username} (@{user.username})\n                                </option>\n                              ))}\n                            </select>\n                          </div>\n                        </div>\n\n                        <button type=\"button\" onClick={handleAssignTreePosition} className=\"w-full py-2.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 font-black text-xs transition flex items-center justify-center gap-2\">\n                          <UserCheck className=\"w-3.5 h-3.5\" />\n                          <span>Atribuir / mover membro</span>\n                        </button>\n\n                        <div className=\"space-y-1\">\n                          <div className=\"text-[10px] uppercase tracking-wide text-slate-500 font-bold\">Posições ocupadas</div>\n                          {adminTreePositions.filter(pos => pos.status === 'occupied').map(pos => (\n                            <div key={pos.position_index} className=\"flex items-center justify-between gap-2 p-2 bg-slate-950 border border-slate-800 rounded-xl\">\n                              <div>\n                                <div className=\"font-mono text-slate-200\">#{pos.position_index} · @{pos.username}</div>\n                                <div className=\"text-[10px] text-slate-500\">{pos.full_name || 'Membro sem nome exibido'}</div>\n                              </div>\n                              <button type=\"button\" onClick={() => handleClearTreePosition(pos.position_index)} className=\"text-[10px] text-rose-300 hover:text-rose-200 underline\">\n                                Liberar\n                              </button>\n                            </div>\n                          ))}\n                        </div>\n                      </div>'''
s = s.replace("                      {renderActiveModel(adminTreePositions)}", ui, 1)
p.write_text(s, encoding='utf-8')
print('step c ok')
